        if acc:
            acc.update({"depth": 0, "route": "jne_fallthrough"})
            return [acc]
        if ins.mnemonic == "ret":
            break
    return []


def local_accesses(pe, md, site):
    if site["branch"] not in DIRECT_FIELD_BRANCHES:
